// Lê queries de prospecção do env. Formato:
// PROSPECT_QUERIES_GMAPS = JSON array. Ex:
// [
//   {"search": "agência de marketing em Mogi das Cruzes", "max": 5},
//   {"search": "restaurante em Arujá", "max": 5}
// ]
let queries = [];
try {
  queries = JSON.parse($env.PROSPECT_QUERIES_GMAPS || '[]');
} catch (e) {
  return [];
}
return queries.map(q => ({ json: q }));

// Lê queries do Instagram do env. Formato:
// PROSPECT_QUERIES_INSTAGRAM = JSON array. Ex:
// [
//   {"hashtag": "empresariomogi", "max": 5},
//   {"username": "perfil_concorrente", "max": 5, "type": "followers"}
// ]
let queries = [];
try {
  queries = JSON.parse($env.PROSPECT_QUERIES_INSTAGRAM || '[]');
} catch (e) {
  return [];
}
return queries.map(q => ({ json: q }));

// Normaliza resultado do Google Maps Places (Apify compass actor)
const items = Array.isArray($input.all()) ? $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]) : [];
const leads = [];
for (const item of items) {
  if (!item || !item.title) continue;
  const whatsapp = (item.phone || item.phoneUnformatted || '').replace(/\D/g, '');
  if (!whatsapp || whatsapp.length < 10) continue; // sem telefone, sem prospecção
  leads.push({
    nome: item.title,
    empresa: item.title,
    whatsapp,
    site: item.website || '',
    instagram: item.instagrams?.[0] || '',
    setor: item.categoryName || 'Outro',
    origem: 'Google Maps',
    gatilho: `Encontrada via Google Maps: ${item.categoryName || ''} em ${item.city || item.address || ''}`,
    cargo: '',
    linkedin: '',
    cidade: item.city || '',
    endereco: item.address || ''
  });
}
return leads.map(l => ({ json: l }));

// Normaliza resultado do Instagram Hashtag Scraper
// IMPORTANTE: Instagram não expõe WhatsApp direto. Aqui criamos lead com handle do IG
// e o WhatsApp será extraído do bio depois (via outro actor) ou preenchido manualmente.
const items = Array.isArray($input.all()) ? $input.all().flatMap(i => Array.isArray(i.json) ? i.json : [i.json]) : [];
const leads = [];
const seen = new Set();
for (const item of items) {
  const owner = item.ownerUsername || item.owner?.username;
  if (!owner || seen.has(owner)) continue;
  seen.add(owner);
  leads.push({
    nome: item.ownerFullName || owner,
    empresa: item.ownerFullName || owner,
    whatsapp: '', // a preencher manualmente após análise do perfil
    site: '',
    instagram: `https://instagram.com/${owner}`,
    setor: 'Outro',
    origem: 'Instagram',
    gatilho: `Encontrado via hashtag #${item.hashtag || ''} — post: ${item.caption?.slice(0, 80) || ''}`,
    cargo: '',
    linkedin: '',
    cidade: '',
    endereco: ''
  });
}
return leads.map(l => ({ json: l }));

// Deduplica: remove leads que já existem no Notion (por WhatsApp ou Instagram)
const newLeads = $('Junta fontes').all().map(i => i.json);
const existing = $('Notion: leads existentes').all().map(i => i.json);

const existingWhats = new Set();
const existingInsta = new Set();
for (const e of existing) {
  const props = e.property || e.properties || {};
  const wpp = (props.WhatsApp?.phone_number || '').replace(/\D/g, '');
  const insta = props.Instagram?.url || '';
  if (wpp) existingWhats.add(wpp);
  if (insta) existingInsta.add(insta.replace(/\/$/, ''));
}

const dedup = [];
const seenNow = new Set();
for (const lead of newLeads) {
  const key = lead.whatsapp || lead.instagram;
  if (!key || seenNow.has(key)) continue;
  if (lead.whatsapp && existingWhats.has(lead.whatsapp)) continue;
  if (lead.instagram && existingInsta.has(lead.instagram.replace(/\/$/, ''))) continue;
  seenNow.add(key);
  dedup.push(lead);
}
return dedup.map(l => ({ json: l }));

